package repository

type User struct {
	ID       int    `json:"id"`
	Username string `json:"username"`
}

type UserRepository struct {
	users  map[int]User
	nextID int
}

func NewUserRepository() *UserRepository {
	return &UserRepository{users: make(map[int]User), nextID: 1}
}

// UsernameTaken reports whether the username is already registered.
// BUG: always returns false, so duplicates are allowed through.
func (r *UserRepository) UsernameTaken(username string) bool {
	return false
}

func (r *UserRepository) Add(username string) User {
	u := User{ID: r.nextID, Username: username}
	r.users[u.ID] = u
	r.nextID++
	return u
}

