package main

import (
	"encoding/json"
	"net/http"
	"net/http/httptest"
	"strings"
	"testing"
)

func TestUniqueUsername(t *testing.T) {
	r := SetupRouter()

	post := func(username string) (int, map[string]interface{}) {
		req := httptest.NewRequest("POST", "/users", strings.NewReader(`{"username":"`+username+`"}`))
		req.Header.Set("Content-Type", "application/json")
		w := httptest.NewRecorder()
		r.ServeHTTP(w, req)
		var m map[string]interface{}
		json.Unmarshal(w.Body.Bytes(), &m)
		return w.Code, m
	}

	code, m := post("ada")
	if code != http.StatusCreated || m["id"].(float64) != 1 {
		t.Fatalf("first register: %d %v", code, m)
	}
	if code, _ := post("ada"); code != http.StatusConflict {
		t.Fatalf("duplicate must be 409, got %d", code)
	}
	code, m = post("bob")
	if code != http.StatusCreated || m["id"].(float64) != 2 {
		t.Fatalf("rejected duplicate consumed an id: bob got %v (want id 2)", m)
	}
}

